import { useRouter } from "next/router";
import { useState } from "react";

const PropertyDetail = () => {
  const router = useRouter();
  const [city, setCity] = useState("");

  const handleSearch = () => {
    if (city.trim() !== "") {
      router.push(`/booking/${city}`);
    }
  };

  return (
    <div className="p-4 md:p-8 w-full max-w-7xl mx-auto">
      {/* Header */}
      <div className="flex flex-col md:flex-row justify-between items-center mb-6 gap-4">
        {/* Search Bar */}
        <div className="flex items-center gap-2 w-full md:w-auto">
          <input
            type="text"
            placeholder="Enter city"
            className="w-full md:w-64 p-2 border border-gray-300 rounded-md focus:outline-none"
            value={city}
            onChange={(e) => setCity(e.target.value)}
          />
          <button
            onClick={handleSearch}
            className="bg-blue-600 text-white px-4 py-2 rounded-md hover:bg-blue-700 transition"
          >
            Search
          </button>
        </div>

        {/* User Section */}
        <div className="flex items-center gap-4">
          <button className="text-gray-600 hover:text-black">Sign In</button>
          <button className="bg-green-600 text-white px-4 py-2 rounded-md hover:bg-green-700">
            Register
          </button>
        </div>
      </div>

      {/* Main Content */}
      <div className="flex flex-col lg:flex-row gap-8">
        {/* Property Images */}
        <div className="w-full lg:w-2/3">
          <img
            src="https://source.unsplash.com/random/800x500"
            alt="Property"
            className="w-full rounded-lg shadow-md"
          />
          {/* Thumbnails */}
          <div className="flex gap-2 mt-4 overflow-x-auto">
            {Array(4)
              .fill(null)
              .map((_, index) => (
                <img
                  key={index}
                  src={`https://source.unsplash.com/random/200x150?sig=${index}`}
                  alt="Thumbnail"
                  className="w-24 h-16 object-cover rounded-md cursor-pointer hover:opacity-75 transition"
                />
              ))}
          </div>
        </div>

        {/* Booking Section */}
        <div className="w-full lg:w-1/3 p-4 bg-gray-100 rounded-lg shadow-md">
          <h2 className="text-xl font-semibold mb-3">Book Your Stay</h2>
          <p className="text-gray-700 text-sm mb-4">Select your dates and number of guests.</p>

          <label className="block text-gray-600">Check-in</label>
          <input
            type="date"
            className="w-full p-2 border border-gray-300 rounded-md mb-3"
          />

          <label className="block text-gray-600">Check-out</label>
          <input
            type="date"
            className="w-full p-2 border border-gray-300 rounded-md mb-3"
          />

          <label className="block text-gray-600">Guests</label>
          <select className="w-full p-2 border border-gray-300 rounded-md mb-4">
            <option>1 Guest</option>
            <option>2 Guests</option>
            <option>3 Guests</option>
            <option>4+ Guests</option>
          </select>

          <button className="w-full bg-blue-600 text-white py-2 rounded-md hover:bg-blue-700">
            Book Now
          </button>
        </div>
      </div>
    </div>
  );
};

export default PropertyDetail;
